function profileBackup(profile){const data=storage(profile.id).state,backup={app:'LABELONZEWAY',version:4,exportedAt:new Date().toISOString(),profile:{...profile},data:{shop:{...data.shop},addr:[...(data.addr||[])],manifest:[...(data.manifest||[])],archive:[...(data.archive||[])],counter:Number(data.counter)||0,labelVault:[...(data.labelVault||[])],gateway:{...data.gateway},draft:{...data.draft}}};return{backup,data,fileName:`theta77-${sanitizeBackupName(profile.name)}-backup-${new Date().toISOString().slice(0,10)}.json`}}
function downloadProfileBackup(profile,onResult){try{const result=profileBackup(profile),content=JSON.stringify(result.backup,null,2),blob=new Blob([content],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=result.fileName;anchor.setAttribute('aria-hidden','true');anchor.style.position='fixed';anchor.style.left='-9999px';document.body.append(anchor);anchor.click();anchor.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);onResult?.({ok:true,result})}catch(error){onResult?.({ok:false,error})}}
function showProfileBackupResult(modal,response){const target=modal?.querySelector('[data-profile-backup-status]');if(!target)return;target.className=`profile-backup-status${response.ok?'':' error'}`;if(response.ok){const profile=response.result.backup.profile,name=profile.name||'Unnamed profile',count=response.result.data.addr.length,parcels=response.result.data.manifest.length+response.result.data.archive.length;target.textContent=`Backup downloaded successfully\nProfile: ${name}\nCustomers: ${count}\nParcels: ${parcels}\nDate: ${response.result.backup.exportedAt}`}else target.textContent=`Backup could not be downloaded: ${response.error?.message||'unknown download error'}`}
function openContactEditor(parent,customer={},draw){const modal=document.createElement('div');modal.className='modal-backdrop';modal.dataset.contactEditor='';modal.innerHTML=`<section class="contact-editor" role="dialog" aria-modal="true" aria-label="${customer.id?'Edit customer':'New customer'}"><header><div><h2>${customer.id?'Edit customer':'New customer'}</h2><p>Save a trusted historical address as entered; operational address checks apply only to OCR/manual validation.</p></div><button class="button ghost" type="button" data-contact-cancel aria-label="Close contact editor">Cancel</button></header><div class="contact-editor-fields"><div class="field"><label>Name</label><input data-c="name" aria-label="Name" value="${esc(customer.name)}" autocomplete="name"><small data-contact-error="name"></small></div><div class="field"><label>Phone</label><input data-c="phone" aria-label="Phone" value="${esc(customer.phone)}" autocomplete="tel"><small data-contact-error="phone"></small></div><div class="field"><label>Area</label><input data-c="area" aria-label="Area" value="${esc(customer.area)}"><small data-contact-error="area"></small></div><div class="field"><label>Address</label><textarea data-c="address" aria-label="Address">${esc(customer.address)}</textarea><small data-contact-error="address"></small></div><div class="field"><label>Note</label><textarea data-c="note" aria-label="Note">${esc(customer.note)}</textarea></div></div><p class="contact-editor-error" data-contact-editor-error role="alert"></p><footer class="actions"><button class="button sand" data-contact-save-use>Save and use on label</button><button class="button ghost" data-contact-save>Save only</button><button class="button ghost" data-contact-cancel>Cancel</button></footer></section>`;document.body.append(modal);const close=()=>modal.remove(),saveContact=use=>{try{const c=customerData(modal,customer.id||'');const existing=state.addr.find(item=>item.id===customer.id);if(existing)Object.assign(existing,c);else state.addr.push(c);if(use)state.draft.customerId=c.id;save();close();draw()}catch(error){modal.querySelector('[data-contact-editor-error]').textContent=error.message||'Please correct the highlighted fields.';const field=/name|phone|address/i.exec(error.message||'')?.[0];if(field){const target=modal.querySelector(`[data-contact-error="${field.toLowerCase()}"]`);if(target)target.textContent=error.message}}};modal.querySelectorAll('[data-contact-cancel]').forEach(button=>button.onclick=close);modal.querySelector('[data-contact-save-use]').onclick=()=>saveContact(true);modal.querySelector('[data-contact-save]').onclick=()=>saveContact(false);modal.onclick=event=>{if(event.target===modal)close()};modal.querySelector('[data-c="name"]').focus()}
function labelFields(){const d=state.draft;return `<div class="two"><div class="field"><label>Quantity</label><input data-d="qty" type="number" min="1" value="${d.qty}"></div><div class="field"><label>Unit price</label><input data-d="price" type="number" min="0" value="${d.price}"></div></div><div class="two"><div class="field"><label>Collect (override optional)</label><input data-d="cod" type="number" min="0" placeholder="Auto from quantity × price" value="${d.cod}"></div><div class="field"><label>Sales fee</label><input data-d="salesFee" type="number" min="0" value="${d.salesFee}"></div></div><div class="two"><div class="field"><label>Delivery fee</label><input data-d="ship" type="number" min="0" value="${d.ship}"></div><div class="field"><label>Payment</label><select data-d="pay"><option ${d.pay==='COD'?'selected':''}>COD</option><option ${d.pay==='Paid'?'selected':''}>Paid</option></select></div></div><div class="two"><div class="field"><label>Delivery date</label><input data-d="deliverAt" type="date" value="${d.deliverAt}"></div><div class="field"><label>Time</label><input data-d="deliverTime" type="time" value="${d.deliverTime}"></div></div><div class="field"><label>Reference</label><input data-d="reference" value="${esc(d.reference)}"></div><div class="field"><label>Notes</label><textarea data-d="notes">${esc(d.notes)}</textarea></div>`}
function preview(){return'<canvas class="label-preview-canvas" data-label-preview aria-label="Immediate SHIPDESK 72 millimetre label preview"></canvas>'}
async function paintPreview(rootNode){const c=state.addr.find(x=>x.id===state.draft.customerId),d=state.draft,shop=currentLabelShop(),parcel={...d,oid:'PREVIEW',rec:c||{name:'Select a saved customer',phone:'',address:''},cod:draftCollect(d),addedAt:new Date().toISOString(),deliverAt:d.deliverAt||'',qty:d.qty||1,price:d.price||0,ship:d.ship||0,pay:d.pay||'COD'};await paintLabelCanvas(rootNode,parcel,shop)}
function openPreviewModal(canvas){if(!canvas)return;const modal=document.createElement('div');modal.className='modal-backdrop';modal.dataset.previewDialog='';modal.innerHTML=`<section class="preview-modal" role="dialog" aria-modal="true" aria-label="Label preview"><header><h2>Label preview</h2><button class="button ghost" data-preview-close aria-label="Close enlarged label preview">Close</button></header><div data-preview-large></div></section>`;const copy=canvas.cloneNode();copy.removeAttribute('data-label-preview');copy.className='label-preview-large';copy.width=canvas.width;copy.height=canvas.height;copy.getContext('2d').drawImage(canvas,0,0);modal.querySelector('[data-preview-large]').append(copy);document.body.append(modal);modal.querySelector('[data-preview-close]').onclick=()=>modal.remove();modal.onclick=event=>{if(event.target===modal)modal.remove()}}
function saveParcel(){if(busy)return;const c=state.addr.find(x=>x.id===state.draft.customerId);if(state.draft.price==='')throw Error('Unit price is required');busy=true;try{const p=createParcel(state.draft,c,0,new Date(),state.manifest,currentLabelShop());state.manifest.push(p);state.labelVault.push(p);state.draft=blankDraft();save();return p}finally{busy=false}}
function command(){const r=root('Command',`<section class="grid-command"><section class="card customer-desk"><div class="section-heading"><div><h2>Customer Desk</h2><p class="section-help">Choose a saved recipient for this label.</p></div><button class="button sand" data-new-customer aria-label="New customer">+ New customer</button></div><input data-search placeholder="Search name, phone, area or address" aria-label="Search customers"><div class="list scroll" data-customers></div><button class="button ghost full-width" data-delete-selected>Delete selected</button></section><section class="card label-workspace"><h2>Create Label</h2><div data-label-fields>${labelFields()}</div><div class="actions"><button class="button sand" data-save>Save label</button><button class="button teal" data-save-print>Save + Print</button></div><hr><h3>OCR / batch intake</h3><input data-photo type="file" accept="image/*"><button class="button ghost" data-ocr>Scan photo</button><div data-contact></div><div data-batch></div></section><section class="card preview-card"><div class="section-heading"><div><h2>Immediate Preview</h2><p class="section-help">The physical 72 mm label layout.</p></div><button class="button ghost" data-preview-expand aria-label="Open enlarged label preview">Expand</button></div><button class="preview-open" data-preview-open aria-label="Open enlarged label preview"><span data-preview>${preview()}</span></button></section></section><section class="card manifest" data-manifest></section>`),selected=new Set();
 const draw=()=>{r.querySelector('[data-preview]').innerHTML=preview();void paintPreview(r.querySelector('[data-label-preview]')).catch(error=>toast(error.message,true));const q=r.querySelector('[data-search]').value;r.querySelector('[data-customers]').innerHTML=searchCustomers(state.addr,q).map(c=>{const last=state.manifest.filter(p=>p.rec.id===c.id).at(-1);return`<article class="customer-card ${state.draft.customerId===c.id?'selected':''}"><input type="checkbox" class="customer-check" data-check="${c.id}" aria-label="Select ${esc(c.name)}" ${selected.has(c.id)?'checked':''}><button class="customer-main" data-use="${c.id}"><b>${esc(c.name||'Unnamed customer')}</b><span>${esc(c.phone||'No phone')}</span><span>${esc(c.area||'No area')}</span><small>${esc((c.address||'No address').replace(/\s+/g,' ').slice(0,72))}</small></button><div class="customer-actions"><button class="icon-button" data-edit="${c.id}" aria-label="Edit ${esc(c.name)}" title="Edit">✎</button><button class="icon-button danger" data-delete="${c.id}" aria-label="Delete ${esc(c.name)}" title="Delete">×</button></div>${last?`<small class="customer-history">Previous: ${last.oid} · ${labels[statusOf(last)]}</small>`:''}</article>`}).join('')||'<p class="empty-state">No saved customers.</p>';drawManifest(r)};draw();
 r.querySelector('[data-search]').oninput=draw;r.onclick=async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.newCustomer!==undefined){openContactEditor(r,{},draw)}else if(b.dataset.previewOpen!==undefined||b.dataset.previewExpand!==undefined){openPreviewModal(r.querySelector('[data-label-preview]'))}else if(b.dataset.use){state.draft.customerId=b.dataset.use;save();draw()}else if(b.dataset.edit){const c=state.addr.find(x=>x.id===b.dataset.edit);openContactEditor(r,c,draw)}else if(b.dataset.delete){if(confirm('Delete this one customer? This does not delete existing labels.')){state.addr=deleteCustomers(state.addr,[b.dataset.delete]);save();draw()}}else if(b.dataset.deleteSelected){if(selected.size&&confirm(`Delete ${selected.size} selected customers?`)){state.addr=deleteCustomers(state.addr,[...selected]);save();draw()}}else if(b.dataset.save!==undefined||b.dataset.savePrint!==undefined){const p=saveParcel();toast(`Saved ${p.oid}`);if(b.dataset.savePrint!==undefined)printParcel(p);command()}else if(b.dataset.ocr!==undefined){const f=r.querySelector('[data-photo]').files[0];r.querySelector('[data-contact]').textContent='Scanning…';const contact=await ocrPhoto(f);r.querySelector('[data-contact]').innerHTML=contactPanel(contact);bindContact(r,contact,draw)}}catch(x){toast(x.message,true)}};
 r.querySelector('[data-customers]').onchange=e=>{if(e.target.dataset.check)e.target.checked?selected.add(e.target.dataset.check):selected.delete(e.target.dataset.check)};r.querySelectorAll('[data-d]').forEach(x=>x.oninput=()=>{state.draft[x.dataset.d]=x.value;save();draw()});r.querySelector('[data-ocr]').dataset.ocr=''}
function batchCustomerOptions(selected=''){return`<option value="">Choose customer</option>${state.addr.map(c=>`<option value="${c.id}" ${c.id===selected?'selected':''}>${esc(c.name)} · ${esc(c.phone)}</option>`).join('')}`}
function batchRowHtml(row){const contact=row.contact||{},existing=state.addr.find(c=>c.phone&&c.phone===contact.phone),collectValue=batchCollect(row),panel=row.contactOpen?`<aside class="notice contact"><b>Detected contact</b><div class="two"><input data-contact-name="${row.id}" value="${esc(contact.name)}" placeholder="Name"><input data-contact-phone="${row.id}" value="${esc(contact.phone)}" placeholder="Phone"></div><input data-contact-address="${row.id}" value="${esc(contact.address)}" placeholder="Address"><small>${row.price===''?'Price not found — enter manually.':`Detected price: ${money(row.price)}`}</small>${existing?`<small>Previous shipment: ${(state.manifest.filter(p=>p.rec.id===existing.id).at(-1)||{}).oid||'none'}</small>`:''}<div class="actions">${existing?`<button data-batch-use="${row.id}">Use Same Details</button>`:`<button data-batch-save-contact="${row.id}">Save Contact</button>`}<button data-batch-save-contact="${row.id}">Edit + Save</button><button data-batch-skip="${row.id}">Skip</button></div></aside>`:'';return`<article class="card batch-row"><input type="checkbox" data-batch-select="${row.id}" ${row.selected?'checked':''}><img class="batch-thumb" src="${row.image}" alt="${esc(row.fileName||'Batch photo')}"><div><b>${esc(row.fileName||'Photo')}</b><span class="status ${row.status}">${esc(row.status.replaceAll('_',' '))}</span>${row.error?`<p class="error">${esc(row.error)}</p>`:''}<div class="two"><label>Qty <input data-batch-field="qty" data-row="${row.id}" type="number" min="1" value="${row.qty}"></label><label>Copies <input data-batch-field="copies" data-row="${row.id}" type="number" min="1" value="${row.copies}"></label><label>Unit price <input data-batch-field="price" data-row="${row.id}" type="number" min="0" value="${row.price}"></label><label>Collect <input data-batch-field="cod" data-row="${row.id}" type="number" min="0" placeholder="Auto" value="${row.cod}"></label><label>Delivery <input data-batch-field="ship" data-row="${row.id}" type="number" min="0" value="${row.ship}"></label><label>Payment <select data-batch-field="pay" data-row="${row.id}"><option ${row.pay==='COD'?'selected':''}>COD</option><option ${row.pay==='Paid'?'selected':''}>Paid</option></select></label></div><label>Customer <select data-batch-field="customerId" data-row="${row.id}">${batchCustomerOptions(row.customerId)}</select></label><p>Collect: <b>${money(collectValue)||'—'}</b> · Delivery: ${money(row.ship)||'—'}</p><div class="actions"><button data-batch-scan="${row.id}">Scan / Rescan</button><button data-batch-open="${row.id}">Contact</button><button data-batch-print="${row.id}">Print row</button><button data-batch-add-manifest="${row.id}">Add to Manifest</button></div>${panel}</div></article>`}
function renderBatch(r){const target=r.querySelector('[data-batch]');if(!target)return;target.innerHTML=`<div class="card"><h3>Batch rows</h3><div class="actions"><select data-batch-apply-customer>${batchCustomerOptions()}</select><button data-batch-apply>Apply customer to selected/all</button><button data-batch-all>Select All</button><button data-batch-delete>Delete Selected</button><button data-batch-clear>Clear Batch</button><button data-batch-merge>Merge same customer</button><button data-batch-print-selected>Print Selected</button><button data-batch-add-selected>Add Selected to Manifest</button><button data-batch-print-all>Print All</button><button data-batch-add-all>Add All to Manifest</button></div><div class="list" data-batch-list>${state.batch.map(batchRowHtml).join('')||'<p>No batch photos queued.</p>'}</div></div>`;bindBatch(r)}
function rowById(id){return state.batch.find(x=>x.id===id)}
function batchContactFromInputs(r,id){const row=rowById(id);return{name:r.querySelector(`[data-contact-name="${id}"]`)?.value||row.contact?.name||'',phone:r.querySelector(`[data-contact-phone="${id}"]`)?.value||row.contact?.phone||'',address:r.querySelector(`[data-contact-address="${id}"]`)?.value||row.contact?.address||''}}
function addBatchParcel(row){if(row.addedParcelIds?.length)throw Error('This row was already added to the Manifest');const[p]=addBatchRowsToManifest([row],[row.id],state.addr,state.manifest,new Date(),currentLabelShop());state.manifest.push(p);state.labelVault.push(p);row.addedParcelIds=[p.id];row.status='added_to_manifest';save();return p}
async function scanBatchRow(r,row){const file=batchFiles.get(row.id);if(!file)throw Error('Original photo is unavailable after reload. Select it again to rescan.');row.status='scanning';row.error='';renderBatch(r);try{const contact=await ocrPhoto(file);row.contact=contact;row.price=contact.price===''?row.price:contact.price;const existing=state.addr.find(c=>c.phone&&c.phone===contact.phone);row.customerId=existing?.id||row.customerId;row.contactOpen=true;row.status='contact_requires_confirmation';save()}catch(e){row.status='error';row.error=e.message;save()}renderBatch(r)}
function bindBatch(r){const box=r.querySelector('[data-batch]');box.onchange=e=>{const el=e.target,row=rowById(el.dataset.row);if(el.dataset.batchSelect){rowById(el.dataset.batchSelect).selected=el.checked;save();return}if(el.dataset.batchField&&row){row[el.dataset.batchField]=el.value;row.status=row.customerId?'ready':'queued';save();renderBatch(r)}};box.onclick=async e=>{const b=e.target.closest('button');if(!b)return;e.stopPropagation();try{const chosen=state.batch.filter(x=>x.selected),all=state.batch;if(b.dataset.batchAll!==undefined){const next=!all.length||!all.every(x=>x.selected);all.forEach(x=>x.selected=next);save();renderBatch(r)}else if(b.dataset.batchApply!==undefined){const id=box.querySelector('[data-batch-apply-customer]').value,rows=chosen.length?chosen:all;if(!id)throw Error('Choose a customer to apply');rows.forEach(x=>{x.customerId=id;x.status='ready'});save();renderBatch(r)}else if(b.dataset.batchDelete!==undefined){if(chosen.length&&confirm(`Delete ${chosen.length} selected batch rows?`)){state.batch=all.filter(x=>!x.selected);save();renderBatch(r)}}else if(b.dataset.batchClear!==undefined){if(confirm('Clear every batch row? This cannot be undone.')){state.batch=[];save();renderBatch(r)}}else if(b.dataset.batchMerge!==undefined){const result=mergeBatchRows(all,chosen.map(x=>x.id));if(!result.merged)throw Error('Select two or more rows for the same confirmed customer and telephone');state.batch=result.rows;save();renderBatch(r)}else if(b.dataset.batchScan)await scanBatchRow(r,rowById(b.dataset.batchScan));else if(b.dataset.batchOpen){const row=rowById(b.dataset.batchOpen);row.contactOpen=true;renderBatch(r)}else if(b.dataset.batchSkip){const row=rowById(b.dataset.batchSkip);row.contactOpen=false;row.status=row.customerId?'ready':'queued';save();renderBatch(r)}else if(b.dataset.batchUse){const row=rowById(b.dataset.batchUse),existing=state.addr.find(c=>c.phone===row.contact.phone);if(!existing)throw Error('Existing customer no longer available');row.customerId=existing.id;row.contactOpen=false;row.status='ready';save();renderBatch(r)}else if(b.dataset.batchSaveContact){const row=rowById(b.dataset.batchSaveContact),c=upsertCustomer(state.addr,createCustomer(batchContactFromInputs(r,row.id)));row.customerId=c.id;row.contact={...row.contact,...c};row.contactOpen=false;row.status='ready';save();renderBatch(r)}else if(b.dataset.batchAddManifest){addBatchParcel(rowById(b.dataset.batchAddManifest));renderBatch(r);drawManifest(r)}else if(b.dataset.batchPrint){const row=rowById(b.dataset.batchPrint),p=row.addedParcelIds?.length?state.manifest.find(x=>x.id===row.addedParcelIds[0]):createParcel({qty:row.qty,price:row.price,cod:row.cod,ship:row.ship,pay:row.pay},state.addr.find(c=>c.id===row.customerId),0,new Date(),state.manifest);printParcel(p);row.printed=true;row.status='printed';save();renderBatch(r)}else if(b.dataset.batchAddSelected!==undefined||b.dataset.batchAddAll!==undefined){const rows=b.dataset.batchAddSelected!==undefined?chosen:all;rows.forEach(addBatchParcel);renderBatch(r);drawManifest(r)}else if(b.dataset.batchPrintSelected!==undefined||b.dataset.batchPrintAll!==undefined){const rows=b.dataset.batchPrintSelected!==undefined?chosen:all;rows.forEach(row=>{const p=row.addedParcelIds?.length?state.manifest.find(x=>x.id===row.addedParcelIds[0]):createParcel({qty:row.qty,price:row.price,cod:row.cod,ship:row.ship,pay:row.pay},state.addr.find(c=>c.id===row.customerId),0,new Date(),state.manifest);printParcel(p);row.printed=true;row.status='printed'});save();renderBatch(r)}}catch(x){toast(x.message,true)}}}
async function addBatchPhotos(r,files){for(const file of files){const image=await new Promise((ok,bad)=>{const reader=new FileReader();reader.onload=()=>ok(reader.result);reader.onerror=bad;reader.readAsDataURL(file)});const row=blankBatchRow({image,fileName:file.name});state.batch.push(row);batchFiles.set(row.id,file)}save();renderBatch(r)}
function bindContact(r,c,draw){r.querySelector('[data-contact]').onclick=e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.contactSkip!==undefined){r.querySelector('[data-contact]').innerHTML=''}else if(b.dataset.contactUse!==undefined){state.draft={...state.draft,...c};save();draw();r.querySelector('[data-contact]').innerHTML=''}else if(b.dataset.contactSave!==undefined){const x=upsertCustomer(state.addr,createCustomer(c));state.draft.customerId=x.id;save();draw();r.querySelector('[data-contact]').innerHTML=''}}catch(x){toast(x.message,true)}}}
function drawManifest(r){const t=totals(state.manifest);r.querySelector('[data-manifest]').innerHTML=`<h2>Manifest</h2><div class="actions no-print"><button data-csv>CSV</button><button data-print-selected>Print selected</button><button data-close-day>Close day</button><button data-archive>Archive delivered</button><button data-clear>Clear manifest</button></div><p>Sales ${money(t.sales)} · Delivery ${money(t.delivery)} · COD ${money(t.cod)}</p><div class="table-wrap"><table class="table"><thead><tr><th><input type="checkbox" data-all></th><th>Pick ID</th><th>Customer</th><th>Sales</th><th>Delivery</th><th>COD</th><th>Status</th><th>Actions</th></tr></thead><tbody>${state.manifest.map(p=>`<tr><td><input type="checkbox" data-pick="${p.id}"></td><td><b>${p.oid}</b></td><td>${esc(p.rec.name)}</td><td>${money(p.qty*p.price)}</td><td>${money(p.ship)}</td><td>${money(p.cod)}</td><td><span class="status ${p.deliveryStatus}">${labels[statusOf(p)]}</span></td><td><button data-print-one="${p.id}">Print</button><button data-pdf="${p.id}">PDF</button><button data-png="${p.id}">PNG</button><button data-share="${p.id}">Share</button><button data-duplicate="${p.id}">Duplicate</button><button data-delete-parcel="${p.id}">Delete</button></td></tr>`).join('')||'<tr><td colspan="8">No parcels in this manifest.</td></tr>'}</tbody></table></div>`;bindManifest(r)}
function bindManifest(r){const picks=new Set();r.querySelector('[data-manifest]').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const p=state.manifest.find(x=>x.id===Object.values(b.dataset)[0]);try{if(b.dataset.csv!==undefined)downloadBlob(new Blob([manifestCsv(state.manifest)],{type:'text/csv'}),'manifest.csv');else if(b.dataset.printSelected!==undefined){const rows=state.manifest.filter(x=>picks.has(x.id));if(!rows.length)throw Error('Select at least one label');rows.forEach(printParcel)}else if(b.dataset.closeDay!==undefined){state.manifest.forEach((p,i)=>{if(statusOf(p)==='ready')state.manifest[i]=transition(p,'in_transit')});save();toast('Close day prepared locally: open parcels moved to In transit. Scheduled email/PDF needs Supabase deployment.');drawManifest(r)}else if(b.dataset.archive!==undefined){state.archive.push(...state.manifest.filter(x=>statusOf(x)==='delivered'));state.manifest=state.manifest.filter(x=>statusOf(x)!=='delivered');save();drawManifest(r)}else if(b.dataset.clear!==undefined){if(confirm('Clear all active manifest parcels? Archive/export first.')){state.manifest=[];save();drawManifest(r)}}else if(b.dataset.printOne)printParcel(p);else if(b.dataset.pdf){const rendered=await paintLabelCanvas(document.createElement('canvas'),p,labelShopForParcel(p));downloadBlob(labelRasterPdfBlob(rendered.canvas),`${p.oid}.pdf`)}else if(b.dataset.png){const rendered=await paintLabelCanvas(document.createElement('canvas'),p,labelShopForParcel(p));downloadBlob(await new Promise(resolve=>rendered.canvas.toBlob(resolve,'image/png')),`${p.oid}.png`)}else if(b.dataset.share){const rendered=await paintLabelCanvas(document.createElement('canvas'),p,labelShopForParcel(p)),blob=labelRasterPdfBlob(rendered.canvas);try{await shareFile(blob,`${p.oid}.pdf`)}catch{const url=whatsappLink(p);await navigator.clipboard?.writeText(url);toast(`Secure tracking link unavailable without Supabase. Copied local WhatsApp link: ${url}`)}}else if(b.dataset.duplicate){state.draft={...blankDraft(),customerId:p.rec.id,qty:p.qty,price:p.price,cod:p.cod,ship:p.ship,salesFee:p.salesFee,pay:p.pay,notes:p.notes,reference:p.reference};save();toast('Duplicated into the label draft.')}else if(b.dataset.deleteParcel){if(confirm(`Delete label ${p.oid}?`)){state.manifest=state.manifest.filter(x=>x.id!==p.id);save();drawManifest(r)}}}catch(x){toast(x.message,true)}};r.querySelector('[data-manifest]').onchange=e=>{if(e.target.dataset.pick)e.target.checked?picks.add(e.target.dataset.pick):picks.delete(e.target.dataset.pick);if(e.target.dataset.all){state.manifest.forEach(p=>e.target.checked?picks.add(p.id):picks.delete(p.id));r.querySelectorAll('[data-pick]').forEach(x=>x.checked=e.target.checked)}}}
