function tracking(){const r=root('Tracking',`<section class="tracking"><div class="card"><h2>Track a parcel</h2><input data-find-input placeholder="Pick ID"><button class="button sand" data-find>Lookup</button><div data-result></div></div></section>`),input=r.querySelector('[data-find-input]');input.value=new URLSearchParams(location.search).get('pick')||'';r.querySelector('[data-find]').onclick=()=>{const p=state.manifest.find(x=>x.oid===input.value)||state.archive.find(x=>x.oid===input.value);r.querySelector('[data-result]').innerHTML=p?`<h3>${p.oid}</h3><p><span class="status ${statusOf(p)}">${labels[statusOf(p)]}</span></p><p>Updated ${esc(p.statusUpdatedAt||p.addedAt||'')}</p>${statusOf(p)==='exception'?`<p>Exception: ${esc(p.exceptionNote)} · ${esc(p.exceptionAt)}</p>`:''}`:'No local parcel found. Public secure tracking requires the reviewed Supabase migration.'};if(input.value)r.querySelector('[data-find]').click()}
function guidedImpl(){const r=root('Guided',`<section class="guided-flow" data-guided-flow><nav class="guided-steps" aria-label="Guided progress">${['Customer','Scan','Price','Confirm'].map((x,i)=>`<button type="button" data-guided-step="${i}">${i+1} ${x}</button>`).join('')}</nav><section class="card guided-panel"><h2 data-guided-heading></h2><div data-guided-body></div><div class="actions guided-actions"><button type="button" class="button ghost" data-guided-back>Back</button><button type="button" class="button teal" data-guided-next>Continue</button></div><p data-guided-result aria-live="polite"></p></section></section>`),d=state.draft&&typeof state.draft==='object'?state.draft:{},steps=['Customer','Scan','Price','Confirm'];let step=Math.max(0,Math.min(3,Number(d.guidedStep)||0)),saving=false;state.draft={...d,guidedStep:step};const persist=()=>{state.draft={...state.draft,guidedStep:step};save()};const result=r.querySelector('[data-guided-result]'),body=r.querySelector('[data-guided-body]'),heading=r.querySelector('[data-guided-heading]'),draw=()=>{heading.textContent=steps[step];r.querySelectorAll('[data-guided-step]').forEach((b,i)=>{b.classList.toggle('active',i===step);b.setAttribute('aria-current',i===step?'step':'false')});r.querySelector('[data-guided-back]').disabled=step===0;r.querySelector('[data-guided-next]').disabled=saving;r.querySelector('[data-guided-next]').textContent=step===3?'Review complete':'Continue';if(step===0){body.innerHTML=`<label class="field"><span>Customer search</span><input data-guided-search value="${esc(state.draft.guidedSearch||'')}" placeholder="Search saved customers" aria-label="Customer search"></label><div data-guided-customers></div><a class="button sand" href="${BASE}command/" data-guided-new>Manage customers in Command</a>`;const search=body.querySelector('[data-guided-search]'),list=body.querySelector('[data-guided-customers]'),render=()=>{const q=search.value.toLowerCase();list.innerHTML=searchCustomers(state.addr,search.value).slice(0,8).map(c=>`<button type="button" class="customer ${c.id===state.draft.customerId?'selected':''}" data-guided-customer="${esc(c.id)}"><b>${esc(c.name)}</b><span>${esc(c.phone||'')} · ${esc(c.address||'')}</span></button>`).join('')||'<p>No saved customer found.</p>'};search.oninput=()=>{state.draft={...state.draft,guidedSearch:search.value};persist();render()};render();}else if(step===1){body.innerHTML=`<label class="field"><span>Scan contact photo</span><input type="file" accept="image/*" data-guided-photo aria-label="Scan contact photo"></label><div data-guided-ocr aria-live="polite">${esc(state.draft.ocrMessage||'Beta — verify detected details before saving.')}</div><div class="actions"><button type="button" class="button ghost" data-guided-rescan>Rescan</button><button type="button" class="button ghost" data-guided-skip>Skip</button><button type="button" class="button teal" data-guided-use-existing>Use Existing</button><button type="button" class="button sand" data-guided-save-contact>Save Contact</button></div>`;body.querySelector('[data-guided-photo]').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;const out=body.querySelector('[data-guided-ocr]');out.textContent='Scanning…';try{const contact=await ocrPhoto(file);state.draft={...state.draft,ocrContact:contact,ocrDecision:'detected',price:contact.price||state.draft.price||'',ocrMessage:contact.name?'Contact detected':'Incomplete contact'};persist();out.textContent=contact.name?`Contact detected: ${contact.name} · ${contact.phone||'phone missing'} · ${contact.price?'Price detected':'Price not found'}`:'Incomplete/invalid contact — enter details manually.'}catch(x){state.draft={...state.draft,ocrDecision:'error',ocrMessage:'OCR error: '+x.message};persist();out.textContent=state.draft.ocrMessage}}}else if(step===2){body.innerHTML=`<div class="two"><label class="field"><span>Quantity</span><input type="number" min="1" data-guided-qty value="${esc(state.draft.qty??1)}"></label><label class="field"><span>Label copies</span><input type="number" min="1" data-guided-copies value="${esc(state.draft.copies??1)}"></label></div><div class="two"><label class="field"><span>Unit price</span><input type="number" min="0" data-guided-price value="${esc(state.draft.price??'')}"></label><label class="field"><span>Delivery fee</span><input type="number" min="0" data-guided-ship value="${esc(state.draft.ship??'')}"></label></div><label class="field"><span>Collect mode</span><select data-guided-cod><option value="auto">Automatic Collect</option><option value="manual">Manual Collect</option></select></label><label class="field"><span>Collect amount</span><input type="number" min="0" data-guided-cod-value value="${esc(state.draft.cod??'')}"></label><div class="two"><label class="field"><span>Payment</span><select data-guided-pay><option>COD</option><option>Paid</option></select></label><label class="field"><span>Delivery date</span><input type="date" data-guided-date value="${esc(state.draft.deliverAt||'')}"></label></div><div class="two"><label class="field"><span>Delivery time</span><input type="time" data-guided-time value="${esc(state.draft.deliverTime||'')}"></label><label class="field"><span>Reference</span><input data-guided-reference value="${esc(state.draft.reference||'')}"></label></div><label class="field"><span>Notes</span><textarea data-guided-notes>${esc(state.draft.notes||'')}</textarea></label>`;body.querySelectorAll('input,select,textarea').forEach(el=>el.oninput=()=>{const map={ 'data-guided-qty':'qty','data-guided-copies':'copies','data-guided-price':'price','data-guided-ship':'ship','data-guided-cod-value':'cod','data-guided-pay':'pay','data-guided-date':'deliverAt','data-guided-time':'deliverTime','data-guided-reference':'reference','data-guided-notes':'notes'};const key=map[el.getAttributeNames().find(a=>map[a])];if(key){state.draft={...state.draft,[key]:el.value};persist()}});body.querySelector('[data-guided-cod]').value=state.draft.codMode||'auto';body.querySelector('[data-guided-cod]').onchange=e=>{state.draft={...state.draft,codMode:e.target.value};persist()};body.querySelector('[data-guided-pay]').value=state.draft.pay||'COD';}else{const customer=state.addr.find(c=>c.id===state.draft.customerId);body.innerHTML=`<div class="preview-card"><h3>Confirm label</h3>${customer?`<p><b>${esc(customer.name)}</b><br>${esc(customer.phone||'')}<br>${esc(customer.address||'')}</p>`:'<p>Select a customer before saving.</p>'}<p>Quantity ${esc(state.draft.qty||1)} · Copies ${esc(state.draft.copies||1)}</p><p>Collect ${money(state.draft.cod||Number(state.draft.qty||1)*Number(state.draft.price||0)+Number(state.draft.ship||0))}</p><div class="preview">${preview()}</div></div><div class="actions"><button type="button" class="button sand" data-guided-save>Save</button><button type="button" class="button teal" data-guided-save-print>Save + Print</button></div>`}};const saveGuidedParcel=async({print=false}={})=>{if(saving)return;saving=true;result.textContent='Saving parcel…';draw();try{if(!state.draft.customerId)throw Error('Select a customer first');if(state.draft.price==='')throw Error('Unit price is required');const parcel=saveParcel();if(print){try{for(let i=0;i<Math.max(1,Number(parcel.copies)||1);i++)printParcel(parcel);result.textContent='Parcel saved and printed.'}catch(x){result.textContent='Parcel saved, printing failed: '+x.message;return}}else result.textContent='Parcel saved: '+parcel.oid}catch(x){result.textContent=x.message||'Could not save parcel.'}finally{saving=false;draw()}};r.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.guidedCustomer){state.draft={...state.draft,customerId:b.dataset.guidedCustomer,ocrDecision:'existing'};persist();draw()}else if(b.dataset.guidedNew){const c=createCustomer({name:'',phone:'',address:'',area:'',note:''});if(c?.name){const saved=upsertCustomer(state.addr,c);state.draft={...state.draft,customerId:saved.id};persist();draw()}}else if(b.dataset.guidedSaveContact){result.textContent='Use the existing contact editor from Command to save a contact.'}else if(b.dataset.guidedUseExisting){state.draft={...state.draft,ocrDecision:'existing'};persist();result.textContent='Existing contact selected.'}else if(b.dataset.guidedSkip){state.draft={...state.draft,ocrDecision:'skipped'};persist();result.textContent='OCR skipped; enter values manually.'}else if(b.dataset.guidedStep){step=Number(b.dataset.guidedStep);persist();draw()}else if(b.dataset.guidedNext){if(step<3){step++;persist();draw()}else saveGuidedParcel({print:false})}else if(b.dataset.guidedBack){step=Math.max(0,step-1);persist();draw()}else if(b.dataset.guidedSave)saveGuidedParcel({print:false});else if(b.dataset.guidedSavePrint)saveGuidedParcel({print:true})};draw();return r}
