function stitchGuided(){const host=document.querySelector('.main');host.innerHTML='<section class="guided-deck"><nav class="guided-steps" aria-label="Guided progress"><b>1 Customer</b><b>2 Scan</b><b>3 Price</b><b>4 Confirm</b></nav><section class="card guided-panel"><h2>Guided label flow</h2><p data-guided-status>Choose a customer to begin.</p><div class="actions"><button type="button" data-guided-back class="button ghost">Back</button><button type="button" data-guided-next class="button teal">Continue</button></div></section></section>';let step=0;const status=host.querySelector('[data-guided-status]'),steps=[ 'Choose a customer to begin.','Scan or confirm the extracted contact.','Set quantity, price and payment.','Review the complete 72mm preview, then save.'];const draw=()=>{status.textContent=steps[step];host.querySelectorAll('.guided-steps b').forEach((x,i)=>x.classList.toggle('active',i===step));host.querySelector('[data-guided-back]').disabled=step===0;host.querySelector('[data-guided-next]').textContent=step===3?'Save':'Continue'};host.querySelector('[data-guided-next]').onclick=()=>{step=Math.min(3,step+1);draw()};host.querySelector('[data-guided-back]').onclick=()=>{step=Math.max(0,step-1);draw()};draw()}
